{
  "title": "A Tasty, Twisty Ubud Sunday",
  "summary": "A slow, food-first day around Ubud with a proper feast, a market-style bite, and one little surprise the crew won't see coming.",
  "stops": [
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle palace wander to ease five night owls into the day. The sun won’t wait, but we won’t rush either.",
      "must_do_id": null
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "A proper local plate for lunch, the kind of stop that feels like a market find without the haggling. Terima kasih (thank you) to whoever suggested more food."
    },
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "Monkeys, mischief, and a little chaos. A surprise twist for a crew that thought they were only here to eat."
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "A bright, breezy vegan stop for a snack-style refuel before the evening proper. I know a guy who swears by the smoothie bowls."
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": "m2",
      "note": "The big splurge dinner stays put. A long, sit-down feast for a crew that loves proper meals and late nights."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "After dark, the beach club lights up. A nightlife finish for the night owls, with the sea close enough to hear."
    }
  ]
}

{
  "title": "Ubud Eats and Unexpected Treats",
  "summary": "A lazy Ubud day built around markets, snacks and one very special dinner, with a surprise stop the crew won't see coming.",
  "stops": [
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "First food stop of the day, a proper local plate to line the stomach. Terima kasih (thank you) to whoever invented chicken rice.",
      "must_do_id": null
    },
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "The surprise: cheeky monkeys and jungle paths. Nobody asked for it, but everybody needs it.",
      "must_do_id": null
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "A market-style vegan pit stop for snacks and smoothies. Keeps the food count climbing without slowing the day.",
      "must_do_id": null
    },
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "A quick palace wander before dinner. History with a side of golden light, and it is free.",
      "must_do_id": null
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": "m2",
      "note": "The kept splurge. A long, slow, unforgettable dinner for a crew of night owls. The sun won't wait, but this table will.",
      "must_do_id": "m2"
    }
  ]
}
